// ---- Opaque optional wrappers ----
//
// Each `OptionalT` wraps a native `Option<T>` and exposes a uniform method
// API to C++ via the cxx bridge. `value()` returns `Result<T>` so misuse
// (calling it on an empty wrapper) throws on the C++ side — same semantics
// as `std::optional::value()` throwing `bad_optional_access`.

macro_rules! optional_type {
    ($name:ident, $inner:ty) => {
        pub struct $name(Option<$inner>);

        impl From<Option<$inner>> for $name {
            fn from(v: Option<$inner>) -> Self {
                Self(v)
            }
        }

        impl $name {
            pub fn has_value(&self) -> bool {
                self.0.is_some()
            }

            pub fn value(&self) -> ::std::result::Result<$inner, ::std::string::String> {
                self.0
                    .clone()
                    .ok_or_else(|| format!("{} has no value", stringify!($name)))
            }

            pub fn value_or(&self, fallback: $inner) -> $inner {
                self.0.clone().unwrap_or(fallback)
            }
        }
    };
}

optional_type!(OptionalBool, bool);
optional_type!(OptionalU8, u8);
optional_type!(OptionalU16, u16);
optional_type!(OptionalU32, u32);
optional_type!(OptionalU64, u64);
optional_type!(OptionalI32, i32);
optional_type!(OptionalString, String);

// ---- Phase-2: data-less cxx-shared enum wrappers ----
//
// Each `optional_enum_type!` invocation generates an opaque `OptionalT`
// wrapper around `Option<schema::E>`. `has_value()` is non-throwing;
// `value()` throws when absent and returns the **cxx-shared** ffi enum
// (which is `Copy`) by value. `value_or(fallback: ffi::E) -> ffi::E`
// accepts the fallback in the ffi enum's coordinates so C++ callers can
// pass an enum constant directly.

macro_rules! optional_enum_type {
    ($name:ident, $schema_ty:path, $ffi_ty:ident) => {
        pub struct $name(Option<$schema_ty>);

        impl From<Option<$schema_ty>> for $name {
            fn from(v: Option<$schema_ty>) -> Self {
                Self(v)
            }
        }

        impl $name {
            pub fn has_value(&self) -> bool {
                self.0.is_some()
            }

            pub fn value(&self) -> ::std::result::Result<$ffi_ty, ::std::string::String> {
                self.0
                    .map(Into::into)
                    .ok_or_else(|| format!("{} has no value", stringify!($name)))
            }

            pub fn value_or(&self, fallback: $ffi_ty) -> $ffi_ty {
                self.0.map(Into::into).unwrap_or(fallback)
            }
        }
    };
}

optional_enum_type!(OptionalRelayMode, SchemaRelayMode, RelayMode);
optional_enum_type!(OptionalSafetyLevel, SchemaSafetyLevel, SafetyLevel);
optional_enum_type!(OptionalJournalMode, SchemaJournalMode, JournalMode);
optional_enum_type!(OptionalSynchronous, SchemaSynchronous, Synchronous);
optional_enum_type!(OptionalTempStore, SchemaTempStore, TempStore);
optional_enum_type!(OptionalSqdbBackend, SchemaSqdbBackend, SqdbBackend);
optional_enum_type!(OptionalInsightServer, SchemaInsightServer, InsightServer);

// ---- Phase-2: polymorphic enum wrappers (Pattern D) ----
//
// Polymorphic enums use a `kind()` discriminant plus per-variant accessors.
// `kind()` throws when absent; numeric accessors throw when the wrong
// variant is active OR when absent.

pub struct OptionalLedgerHistory(Option<SchemaLedgerHistory>);

impl From<Option<SchemaLedgerHistory>> for OptionalLedgerHistory {
    fn from(v: Option<SchemaLedgerHistory>) -> Self {
        Self(v)
    }
}

impl OptionalLedgerHistory {
    pub fn has_value(&self) -> bool {
        self.0.is_some()
    }

    pub fn kind(&self) -> Result<LedgerHistoryKind, String> {
        match self.0 {
            Some(SchemaLedgerHistory::Named(LedgerHistoryName::Full)) => {
                Ok(LedgerHistoryKind::Full)
            }
            Some(SchemaLedgerHistory::Named(LedgerHistoryName::None)) => {
                Ok(LedgerHistoryKind::None)
            }
            Some(SchemaLedgerHistory::Numeric(_)) => Ok(LedgerHistoryKind::Numeric),
            None => Err("OptionalLedgerHistory has no value".into()),
        }
    }

    pub fn numeric_value(&self) -> Result<u32, String> {
        match self.0 {
            Some(SchemaLedgerHistory::Numeric(n)) => Ok(n),
            Some(_) => Err("OptionalLedgerHistory is not Numeric".into()),
            None => Err("OptionalLedgerHistory has no value".into()),
        }
    }
}

