        type Voting;
        type Crawl;
        type Vl;

        // ----- Parse outcome (std::expected analogue) -----
        type ParseOutcome;

        // ----- Parse entry points -----
        //
        // These always succeed at the FFI boundary — errors are carried inside
        // the returned `ParseOutcome`. The C++ side discriminates via
        // `has_value()` / `has_error()` and then calls `value()` or `error()`.
        fn parse_from_toml_str(s: &str) -> Box<ParseOutcome>;
        fn parse_from_ini_str(s: &str) -> Box<ParseOutcome>;
        fn parse_from_file(path: &str) -> Box<ParseOutcome>;

        // ----- ParseOutcome methods -----
        //
        // `value()` and `error()` use cxx `Result<T>` so that misuse
        // (calling `value()` on an error, or `error()` on a success) throws
        // a C++ exception — same semantics as `std::expected::value()`
        // throwing `bad_expected_access` on `unexpected`.
        fn has_value(self: &ParseOutcome) -> bool;
        fn has_error(self: &ParseOutcome) -> bool;
        fn value(self: &mut ParseOutcome) -> Result<Box<Config>>;
        fn error(self: &ParseOutcome) -> Result<String>;

        // ----- Config: top-level scalars -----
        fn network_quorum(self: &Config) -> Box<OptionalU32>;
        fn workers(self: &Config) -> Box<OptionalU32>;
        fn io_workers(self: &Config) -> Box<OptionalU32>;
        fn prefetch_workers(self: &Config) -> Box<OptionalU32>;
        fn max_transactions(self: &Config) -> Box<OptionalU32>;
        fn sweep_interval(self: &Config) -> Box<OptionalU32>;
        fn peers_max(self: &Config) -> Box<OptionalU32>;
        fn peers_in_max(self: &Config) -> Box<OptionalU32>;
        fn peers_out_max(self: &Config) -> Box<OptionalU32>;
        fn validator_list_threshold(self: &Config) -> Box<OptionalU32>;
        fn fee_default(self: &Config) -> Box<OptionalU64>;
        fn path_search(self: &Config) -> Box<OptionalI32>;
        fn path_search_old(self: &Config) -> Box<OptionalI32>;
        fn path_search_fast(self: &Config) -> Box<OptionalI32>;
        fn path_search_max(self: &Config) -> Box<OptionalI32>;
        fn ssl_verify(self: &Config) -> Box<OptionalBool>;
        fn peer_private(self: &Config) -> Box<OptionalBool>;
        fn signing_support(self: &Config) -> Box<OptionalBool>;
        fn elb_support(self: &Config) -> Box<OptionalBool>;
        fn compression(self: &Config) -> Box<OptionalBool>;
        fn ledger_replay(self: &Config) -> Box<OptionalBool>;
        fn beta_rpc_api(self: &Config) -> Box<OptionalBool>;
        fn amendment_majority_time(self: &Config) -> Box<OptionalString>;
        fn debug_logfile(self: &Config) -> Box<OptionalString>;
        fn node_seed(self: &Config) -> Box<OptionalString>;
        fn validation_seed(self: &Config) -> Box<OptionalString>;
        fn validator_token(self: &Config) -> Box<OptionalString>;
        fn validator_key_revocation(self: &Config) -> Box<OptionalString>;
        fn validators_file(self: &Config) -> Box<OptionalString>;
        fn server_domain(self: &Config) -> Box<OptionalString>;
        fn ssl_verify_file(self: &Config) -> Box<OptionalString>;
        fn ssl_verify_dir(self: &Config) -> Box<OptionalString>;
        fn database_path(self: &Config) -> Box<OptionalString>;

        // ----- Config: list-style top-level keys -----
        fn ips(self: &Config) -> &[String];
        fn ips_fixed(self: &Config) -> &[String];
        fn validators(self: &Config) -> &[String];
        fn validator_keys(self: &Config) -> &[String];
        fn validator_list_sites(self: &Config) -> &[String];
