        fn features(self: &Config) -> &[String];
        fn cluster_nodes(self: &Config) -> &[String];
        fn rpc_startup(self: &Config) -> &[String];

        // ----- Config: phase-2 hand-written getters -----
        fn relay_proposals(self: &Config) -> Box<OptionalRelayMode>;
        fn relay_validations(self: &Config) -> Box<OptionalRelayMode>;
        fn ledger_history(self: &Config) -> Box<OptionalLedgerHistory>;
