        fn node_size(self: &Config) -> Box<OptionalNodeSize>;
        fn node_db(self: &Config) -> Box<OptionalNodeDb>;
        fn import_db(self: &Config) -> Box<OptionalNodeDb>;

        // ----- Config: nested tables -----
        //
        // Each nested table has a `has_X()` presence check (non-throwing) and
        // an `X()` ref accessor that throws only if called when `has_X()` is
        // false — programmer-error semantics, no try/catch on the happy path.
        //
        // `unsafe fn` is cxx's required acknowledgement that the explicit
        // lifetimes on the ref returns are sound — the references are tied
        // to `&Config`, which C++ holds via `rust::Box<Config>`. No unsafe
        // call on the C++ side.
        fn has_server(self: &Config) -> bool;
        unsafe fn server<'a>(self: &'a Config) -> Result<&'a Server>;
        fn has_grpc(self: &Config) -> bool;
        unsafe fn grpc<'a>(self: &'a Config) -> Result<&'a Grpc>;
        fn has_overlay(self: &Config) -> bool;
        unsafe fn overlay<'a>(self: &'a Config) -> Result<&'a Overlay>;
        fn has_reduce_relay(self: &Config) -> bool;
        unsafe fn reduce_relay<'a>(self: &'a Config) -> Result<&'a ReduceRelay>;
        fn has_transaction_queue(self: &Config) -> bool;
        unsafe fn transaction_queue<'a>(self: &'a Config) -> Result<&'a TransactionQueue>;
        fn has_hashrouter(self: &Config) -> bool;
        unsafe fn hashrouter<'a>(self: &'a Config) -> Result<&'a HashRouter>;
        fn has_sqlite(self: &Config) -> bool;
        unsafe fn sqlite<'a>(self: &'a Config) -> Result<&'a Sqlite>;
        fn has_sqdb(self: &Config) -> bool;
        unsafe fn sqdb<'a>(self: &'a Config) -> Result<&'a Sqdb>;
        fn has_ledger_tx_tables(self: &Config) -> bool;
        unsafe fn ledger_tx_tables<'a>(self: &'a Config) -> Result<&'a LedgerTxTables>;
        fn has_insight(self: &Config) -> bool;
        unsafe fn insight<'a>(self: &'a Config) -> Result<&'a Insight>;
        fn has_perf(self: &Config) -> bool;
        unsafe fn perf<'a>(self: &'a Config) -> Result<&'a Perf>;
        fn has_voting(self: &Config) -> bool;
        unsafe fn voting<'a>(self: &'a Config) -> Result<&'a Voting>;
        fn has_crawl(self: &Config) -> bool;
        unsafe fn crawl<'a>(self: &'a Config) -> Result<&'a Crawl>;
        fn has_vl(self: &Config) -> bool;
        unsafe fn vl<'a>(self: &'a Config) -> Result<&'a Vl>;

        // ----- Server (shared defaults via flatten) -----
        fn defaults(self: &Server) -> &PortConfig;

        // ----- Server::ports map (Pattern E) -----
        fn port_names(self: &Server) -> Vec<String>;
        fn has_port(self: &Server, name: &str) -> bool;
        unsafe fn port<'a>(self: &'a Server, name: &str) -> Result<&'a PortConfig>;

        // ----- PortConfig getters -----
        fn ip(self: &PortConfig) -> Box<OptionalString>;
        fn port(self: &PortConfig) -> Box<OptionalU16>;
        fn send_queue_limit(self: &PortConfig) -> Box<OptionalU16>;
        fn user(self: &PortConfig) -> Box<OptionalString>;
        fn password(self: &PortConfig) -> Box<OptionalString>;
        fn admin_user(self: &PortConfig) -> Box<OptionalString>;
        fn admin_password(self: &PortConfig) -> Box<OptionalString>;
        fn admin(self: &PortConfig) -> &[String];
        fn secure_gateway(self: &PortConfig) -> &[String];
        fn ssl_key(self: &PortConfig) -> Box<OptionalString>;
        fn ssl_cert(self: &PortConfig) -> Box<OptionalString>;
        fn ssl_chain(self: &PortConfig) -> Box<OptionalString>;
        fn ssl_ciphers(self: &PortConfig) -> Box<OptionalString>;
        fn permessage_deflate(self: &PortConfig) -> Box<OptionalBool>;
        fn client_max_window_bits(self: &PortConfig) -> Box<OptionalU8>;
        fn server_max_window_bits(self: &PortConfig) -> Box<OptionalU8>;
        fn client_no_context_takeover(self: &PortConfig) -> Box<OptionalBool>;
        fn server_no_context_takeover(self: &PortConfig) -> Box<OptionalBool>;
        fn compress_level(self: &PortConfig) -> Box<OptionalU8>;
        fn memory_level(self: &PortConfig) -> Box<OptionalU8>;

        // ----- PortConfig: phase-2 hand-written -----
        fn protocols(self: &PortConfig) -> Vec<Protocol>;
        fn limit(self: &PortConfig) -> Box<OptionalPortLimit>;

        // ----- Grpc -----
        fn ip(self: &Grpc) -> Box<OptionalString>;
        fn port(self: &Grpc) -> Box<OptionalU32>;
        fn secure_gateway(self: &Grpc) -> &[String];
        fn ssl_cert(self: &Grpc) -> Box<OptionalString>;
        fn ssl_key(self: &Grpc) -> Box<OptionalString>;
        fn ssl_cert_chain(self: &Grpc) -> Box<OptionalString>;
        fn ssl_client_ca(self: &Grpc) -> Box<OptionalString>;

        // ----- Overlay -----
        fn public_ip(self: &Overlay) -> Box<OptionalString>;
        fn ip_limit(self: &Overlay) -> Box<OptionalI32>;
        fn max_unknown_time(self: &Overlay) -> Box<OptionalU32>;
