        // ----- ReduceRelay -----
        fn vp_base_squelch_enable(self: &ReduceRelay) -> Box<OptionalBool>;
        fn vp_enable(self: &ReduceRelay) -> Box<OptionalBool>;
        fn vp_base_squelch_max_selected_peers(self: &ReduceRelay) -> Box<OptionalU32>;
        fn tx_enable(self: &ReduceRelay) -> Box<OptionalBool>;
        fn tx_metrics(self: &ReduceRelay) -> Box<OptionalBool>;
        fn tx_min_peers(self: &ReduceRelay) -> Box<OptionalU32>;
        fn tx_relay_percentage(self: &ReduceRelay) -> Box<OptionalU32>;

        // ----- TransactionQueue -----
        fn ledgers_in_queue(self: &TransactionQueue) -> Box<OptionalU32>;
        fn minimum_queue_size(self: &TransactionQueue) -> Box<OptionalU32>;
        fn retry_sequence_percent(self: &TransactionQueue) -> Box<OptionalU32>;
        fn minimum_escalation_multiplier(self: &TransactionQueue) -> Box<OptionalU32>;
        fn minimum_txn_in_ledger(self: &TransactionQueue) -> Box<OptionalU32>;
        fn minimum_txn_in_ledger_standalone(self: &TransactionQueue) -> Box<OptionalU32>;
        fn target_txn_in_ledger(self: &TransactionQueue) -> Box<OptionalU32>;
        fn maximum_txn_in_ledger(self: &TransactionQueue) -> Box<OptionalU32>;
        fn normal_consensus_increase_percent(self: &TransactionQueue) -> Box<OptionalU32>;
        fn slow_consensus_decrease_percent(self: &TransactionQueue) -> Box<OptionalU32>;
        fn maximum_txn_per_account(self: &TransactionQueue) -> Box<OptionalU32>;
        fn minimum_last_ledger_buffer(self: &TransactionQueue) -> Box<OptionalU32>;
        fn zero_basefee_transaction_feelevel(self: &TransactionQueue) -> Box<OptionalU64>;

        // ----- HashRouter -----
        fn hold_time(self: &HashRouter) -> Box<OptionalI32>;
        fn relay_time(self: &HashRouter) -> Box<OptionalI32>;

        // ----- Sqlite -----
        fn page_size(self: &Sqlite) -> Box<OptionalU32>;
